<?php
declare(strict_types=1);
namespace App\Infrastructure\Locator;
use App\ServiceInterface\Locator\LocatorInterface; use SmartResponsor\Strategy\Locator\OpenStreetMapLocator; use SmartResponsor\Strategy\Locator\GoogleLocator; use SmartResponsor\Strategy\Locator\USPSLocator; use SmartResponsor\Integration\Locator\Http\NominatimClient; use SmartResponsor\Integration\Locator\Http\GoogleGeocodingClient; use SmartResponsor\Integration\Locator\Http\USPSClient; use SmartResponsor\Integration\Locator\Decorator\RateLimitedLocator; use SmartResponsor\Integration\Locator\Cache\SimpleArrayCache; use SmartResponsor\Integration\Locator\Decorator\CachedLocator;
final class LocatorSelector{ public function __construct(private readonly LocatorConfig $cfg){}
public function getActiveStrategy(): LocatorInterface{ $base = match(strtolower($this->cfg->strategy)){ 'google' => new GoogleLocator(new GoogleGeocodingClient($this->cfg->googleApiKey)), 'usps' => new USPSLocator(new USPSClient(userId:getenv('USPS_USERID')?:'')), default => new OpenStreetMapLocator(new NominatimClient($this->cfg->nominatimBaseUrl, $this->cfg->nominatimEmail)),}; $wrapped=new RateLimitedLocator($base,120); $wrapped=new CachedLocator($wrapped, new SimpleArrayCache(), 600); return $wrapped; } }
